    visited = [False] * (n + 1)

    tof(n, graph, visited, count)

    s = deque()
    for v in range(1, n + 1):
        if count[v] == 0:
            s.append(v)

    initially_moved = 0
    visited_count = [0] * (n + 1)
    visited_graph = defaultdict(list)

    for i in range(m):
        visited_graph[graph[i][0]].append(graph[i][1])

