import collections

def recover_departments(N, K, pairs):
    departments = [set() for _ in range(N)]
    contacts = collections.defaultdict(list)

    for u, v in pairs:
        departments[u-1].add(v-1)
        departments[v-1].add(u-1)

    for i in range(len(departments)):
        if len(departments[i]) == N:
            continue
        if len(departments[i]) > 1:
            continue

        for j in range(len(departments)):
            if i != j and departments[j] & departments[i]:
                departments[i].update(departments[j])
                break

    for i in range(len(departments)):
        if len(departments[i]) != N:
            continue

        H_index = len(departments[i]) // 2
        departures = set(i for i in range(N) if i in departments[i])

        departures.add(H_index)
        departures.discard(N-1)

        if len(departures) != len(departments[i]):
            continue

        H = H_index + 1
        Q = collections.defaultdict(list)

        for index in departures:
            Q[departments[index]].append(index)

        while Q and Q:
            department_heads = set()
            Q_backup = Q.copy()
            Q.clear()

            for index, contacts in Q.items():
                department_heads.add(index)

            for index, contacts in Q.items():
                if len(contacts) != len(department_heads) + 1:
                    continue

                departures.remove(index)

            for index in departures:
                Q_backup.append((index, departments[index]))

            for department_index in range(N):
                if department_index not in department_heads:
                    first_contact = next((index for index in departures if Q[index]), None)
                    if first_contact is not None and len(departures) == len(Q[0]):  
                        Q[first_contact], Q[department_index] = Q[department_index], Q[first_contact]

            for ship, contact in Q.values():
                if ship not in contact or len(departures) == len(Q[ship]):
                    del Q[ship]
                    if len(Q) == 1 and len(departures) != len(Q[0]):
                        break

            departures.difference_update(Q)

            if departures <= Q_backup:
                if sum(len(contact) == len(departures) for _, contact in Q.items()) == len(Q):
                    H = department_index + 1
                    break

    return len(departments[0] if len(departments) > 0 else []), departures

