from itertools import product

def expected_game_value(n, r, c, changes):
    if n == 1:
        # If only one round, return the root value
        return c if n % 2 else 2 * c + 1

    game_values = [0.5] * (1 << n)  # Initialize with 0.5 for any n-bit binary number
    game_values[(1 << (n-1)) - 1 + pow(2, n-2)] = c

    for change in changes:
        z, g = change
        z ^= (1 << (n-1))
        tmp_values = game_values[:]
        for binary in product([0, 1], repeat=n):
            if sum(x ^ y for x, y in enumerate(binary)) % 2:
                game_values[tuple(binary)] = max(game_values[tuple(binary)], c, g)
            else:
                for k in range(2 ** n):
                    if (k ^ z) == 0:
                        game_values[tuple([x ^ v for x, v in enumerate(binary)] + [k]) ^ 2] = max(game_values[tuple([x ^ v for x, v in enumerate(binary)] + [k]) ^ 2], g)                    
                for bytes_to_cond in range(z):
                    index = 0 if (z & int('0b' + bin(bytes_to_cond)[3:], 2)) else ((z << (n - 1)) - bytes_to_cond) + 1
                    for k in range(2 ** n):
                        if (k & 2 ** index) == 0 or (k ^ ((z << 1) - 1)):
                            game_values[index & k] = max(game_values[index & k], 2 * game_values[index] - game_values[2 ** n - 1 - index], g)
        game_values = []
        for index, v in enumerate(tmp_values):
            if v >= 1:
                game_values.append((v - 1) / 2)
    return game_values

# Example usage
