from collections import defaultdict, deque

def restore_chefcorp(n, k, contacts):
    connections = defaultdict(list)
    for u, v in contacts:
        connections[u].append(v)
        connections[v].append(u)

    visited = [False] * (n + 1)
    connected_components = []

    def dfs(v):
        visited[v] = True
        connected_components.append(v)
        for neighbor in connections[v]:
            if not visited[neighbor]:
                dfs(neighbor)

    for v in range(1, n + 1):
        if not visited[v]:
            dfs(v)
            connected_components.append(v)

    m = len(connected_components)
    assert m <= n
    return (m, *signed_reorder(connected_components))

def signed_reorder(tokens):
    n = len(tokens)
    final_tokens = [0] * n
    in_ans = {0}

    while True:
        for i in range(n):
            if i in in_ans:
                # Add right swaps
                left, right = i - 1, i + 1
                while 0 <= left and 0 <= right and abs(tokens[left] - tokens[right]) < 2 * n:
                    if tokens[left] < tokens[right]:
                        right -= 1
                    else:
                        left += 1
                    tokens[left], tokens[right] = tokens[right], tokens[left]
                    i = right
                tokens[left], tokens[right] = tokens[right], tokens[left]
                i += 1

                # Add left swaps
                left, right = i + 1, i - 1
                while 0 <= left and 0 <= right and abs(tokens[left] - tokens[right]) < 2 * n:
                    if tokens[left] < tokens[right]:
                        left += 1
                    else:
                        right -= 1
                    tokens[left], tokens[right] = tokens[right], tokens[left]
                    i = left
                tokens[left], tokens[right] = tokens[right], tokens[left]
                i -= 1

                while 0 <= left and left not in in_ans and abs(tokens[left]) < n:
                    left -= 1
                while 0 <= right and right not in in_ans and abs(tokens[right]) < n:
                    right += 1
                in_ans.add(left)
                in_ans.add(right)
                in_ans.add(i)

    return ('' if n == 1 else ')') + ''.join(f'({final_tokens[i]})' if i > 0 else '(' for i in in_ans) + ('' if n == 1 else ')')

