def find_matching(n: int, k: int) -> str:
    if 2 * (n / 2) < k or (n & 1) == 0:
        return "NO"
    else:
        return "YES\n" + "\n".join(str(p) + " " + str(q) for p, q in matching_pairs)

def find_matching_pairs(nodes: List[int], edges: List[int]) -> List[List[int]]:
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u-1].append(v-1)
        adj[v-1].append(u-1)
    checking_edges = [[False for _ in range(n)] for _ in range(n)]
    for u in range(n-2, -1, -1):
        for v in adj[u]:
            checking_edges[u][v] = checking_edges[v][u] = True
    matching_pairs = []
    queue = [i for i in range(n-2) if not checking_edges[i]]
    while queue and len(matching_pairs) < n/2:
        u = queue.pop()
        for v in adj[u]:
            if checking_edges[v][u] and not checking_edges[v][u]:
                queue.append(v)
                checking_edges[u][v] = False
                checking_edges[v][u] = False
                matching_pairs.append([u+1, v+1])
                break
    return matching_pairs
