def tof(graph, n):
    neighbors = [[] for _ in range(n)]
    visited = [False] * n
    for u, v in graph:
        neighbors[u - 1].append(v - 1)

    call_count = {i: 0 for i in range(n)}

    def dfs(v):
        visited[v] = True
        call_count[v] += 1
        for u in neighbors[v]:
            if not visited[u]:
                dfs(u)
                call_count[v] += call_count[u]

    min_calls = n * (n - 1) // 2 - n
    for u in range(n - 1, -1, -1):
        for v in neighbors[u]:
            tmp_calls = call_count[v]
            dfs(v)
            call_count[u] = n + n * (n - u - 1) - tmp_calls - call_count[u]

    return call_count
