from typing import Tuple

def count_beautiful_trees(n: int, m: int, a: int, b: int) -> int:
    MOD = 10**9 + 7
    dp = [0] * (m + 1)
    dp[1] = 1
    for i in range(2, m + 1):
        for j in range(1, m + 1):
            dp[max(0, j - i)] = (dp[max(0, j - i)] + dp[j]) % MOD

    def count_trees(n: int, a: int, b: int, dp: Tuple[int, ...]) -> int:
        count = 0
        for i in range(n + 1):
            for j in range(i + 1, n + 1):
                if i != a and j != b:
                    if dp[max(1, j - i)] % MOD == dp[min(j - (i - 1), m):].count(0, i - 1) % MOD:
                        count = (count + dp[j - i]) % MOD
        return count

    return count_trees(n, a, b, *dp)

