            tile = flip_tile(tiles, start_row, start_col)
            tiles[start_row][start_col + 1], tile[start_row][end_col + 1 - start_row] = tile[start_row][end_col + 1 - start_row], tile[start_row][end_col + 1 - start_row]
            tiles[start_row][end_col + 1] = tile[start_row][end_col + 1 - start_row]
            return tiles

def solve_problem(n, m, current_tile, desired_tile):
    tiles = [['U'] * m for _ in range(n)]
    current_tile = flip_tile(tiles, 0, 0)
    desired_tile = flip_tile(desired_tile, 0, 0)
    left_col = 0
    flips, length = 0, len(desired_tile)

    while left_col < m:
        curr_col = max(0, min(left_col + length, m - 1))
        for i in range(left_col, curr_col):
            if i % 2 == 0:  # Left half
                for start_row in range(min(i + 1, left_col - 1), max(i + 1, left_col + length - 1), 2):
                    flag = False
                    for start_col in range(max(0, left_col // 2), min(i, left_col) // 2 + 1, 1):
                        if tiles[start_row][start_col] == 'R':
                            tiles[start_row][i - start_col], tiles[start_row][i - curr_col] = tiles[start_row][i - curr_col], tiles[start_row][i - start_col]
                        elif tiles[start_row][i - start_col] == 'L' and tiles[start_row][i - curr_col] == 'D':
                            flag = True
                            break
                    if not flag:
                        for start_row in range(n - 1, max(n - 1, i - 1), -2):
                            if tiles[start_row][i] == 'L' and tiles[start_row + 1][i] == 'U':
                                flag = True
                                break
                    if flag:
                        left_col += length
                        flips += 1
                        break
                else:
                    return -1
            else:  # Right half
                for start_row in range(max(i + 1, left_col - 1), min(i + 1, left_col + length - 1), 2):
                    flag = False
                    for start_col in range(min(start_row + 1, m - 1), max(start_row + 1, left_col), 1):
                        if tiles[start_row][start_col] == 'U':
                            tiles[start_row][j] = 'D'
                        elif tiles[start_row][start_col] == 'D' and tiles[start_row][j] == 'R':
                            flag = True
                            break
                    if not flag:
                        for start_row in range(i - 1, min(i - 1, left_col + length), -2):
                            tiles[start_row][i] = 'R'
                            if tiles[start_row][left_col + length - 1] == 'L':
                                tiles[start_row][left_col + length - 1] = 'L'
                    if flag:
                        left_col += length
                        flips += 1
                        break
                else:
                    return -1

    return flips

n, m = map(int, input().split())
current_tile = [input().strip() for _ in range(n)]
desired_tile = [input().strip() for _ in range(n)]
if solve_problem(n, m, current_tile, desired_tile) > 100 * 50:
    print(-1)
else:
