from collections import deque

def bake_sumbonn(chtholly, cakes, ops):
    # Initialize the information about cakes not yet baked and possible differences
    not_baked = {i: a for i, a in enumerate(cakes)}
    differences = [0 for _ in range(len(cakes))]
    have_baked = set()

    result = []

    # For each operation of type 1
    for Operation1 in ops:
        l, r, x = Operation1
        for i in range(l - 1, r):
            if cakes[i] > x:
                not_baked[i] = cakes[i] - x
                differences[i] = min(not_baked[i], cakes[i] - x)
        nxt = deque(differences)
        for _ in range(l - 1, r):
            if not nxt and not_baked:
                nxt.appendleft(not_baked.popleft())
            elif have_baked:
                nxt.appendleft(differences[have_baked.pop()])
            else:
                nxt.appendleft(list(not_baked.values())[_.l: _.r].min())
        differences = list(nxt)

    # For each operation of type 2
    for Operation2 in ops:
        l, r, x = Operation2
        if not have_baked:
            res = list(not_baked.values())[_.l: _.r].min()
        else:
            res = differences[have_baked.pop()]
        chocolates = [ch for i, ch in enumerate(cakes) if not have_baked and (ch == x) ^ (ch == res)]
        result.append(len(chocolates))
    return result

