def min_cost_to_reach_leaf(parent, children, costs):
    dp = defaultdict(lambda: float('inf'))
    dp[1] = 0  # Root node already at level 0
    for node in range(2, len(children)):
        node_cost = costs[node]
        parent_cost = dp[parent]
        dp[node] = min(dp[node], parent_cost * node_cost)
    return dp

def calculate_min_cost(parent, child, total, costs):
    if total == 0 or total == parent or total == child:
        cost = costs[total] * child if parent else costs[child]
    else:
        cost, split = parent, 0
        while total:
            last_total = total % child
            split += 1
            cost = min(cost, cost * last_total, cost * child)
            cost = cost // child
        total = last_total
        cost = cost * total
    return cost

def solve(tree, costs):
    children = defaultdict(list)
    for u, v in tree:
        children[v].append(u)
    parent = {node: node for node in range(1, len(costs))}

