from collections import defaultdict, deque

def bfs_path_count(edges, start, N):
    vis = [False] * (N + 1)
    queue = deque([start])
    paths = 0

    while queue:
        node = queue.popleft()
        if vis[node]:
            continue
        paths += 1
        vis[node] = True

        for neighbor in edges[node]:
            if not vis[neighbor]:
                queue.append(neighbor)

    return paths

def solve(N, M, edges):
    cycles = defaultdict(int)
    paths = [1] * (M + 2)

    num_cycles = 0

    for i, (u, v) in enumerate(edges):
        if u == v or num_cycles >= i // 2:
            continue

        cycles[i] += 1
        num_cycles += 1
        paths[i] = 0

        for dx in range(-1, 2):
            y = v + dx

            if not cycles[y]:
                continue

            k = i + cycles[y]

            for z in range(cycles[y]):
                if z == k % cycles[i]:
                    continue

                paths[i] += paths[k]
                paths[k] = 0

    print('\n'.join(map(str, paths[1:])))

if __name__ == '__main__':
