import sys
from collections import defaultdict

def read_file():
    with open("input.txt", "r") as file:
        return file.read().splitlines()

def write_file(filename, content):
    return open(filename, "w").write(f"{content}\n")

def parse_input():
    n, l, w = map(int, input().split())
    edges = defaultdict(list)
    for i in range(n - 1):
        pi, wi = map(int, input().split())
        edges[pi - 1].append((wi, i))
    return n, l, w, edges

def dfs(tree, parent, time):
    for edge in tree:
        if edge[0] == parent:
            continue
        if len(tree[edge[0]]) != 1:
            tree[edge[0]] = (edge[1], time, tree[edge[0]])
        else:
            dfs(tree, edge[0], time + 1)

def main():
    n, l, w, edges = parse_input()
    time = 0
    dfs(edges, -1, time)
    dp = [0 for _ in range(n)]
    for i in range(n):
        for j in range(i + 1, n):
            dp[j] += 1
    dp = dp + [1] + dp
    for edge in edges:
        for i in range(len(dp) - 1, max(0, edge[2]), -1):
            if i == n - 1:
                continue
            if i < edge[0]:
                continue
            if dp[i - 1] + edge[0] <= len(dp) - 2 and dp[i - 1] + edge[0] <= edge[1]:
                dp[i] += dp[i - 1] + 1
    return sum(dp)

if __name__ == "__main__":
    sys.stdout.buffer.write(str(main()).encode("utf8"))
