from collections import defaultdict

def find_close_pairs(n, l, w, edges):
    graph = defaultdict(list)
    for start, end, weight in edges:
        graph[start].append((weight, end))
        graph[end].append((weight, start))

    def dfs(vertex, parent, pathweight, seen, i, weight):
        seen[vertex] = True
        pathweight[i] = weight
        for weight, neighbor in graph[vertex]:
            if neighbor != parent and not seen[neighbor]:
                pathweight, obj1 = dfs(neighbor, vertex, pathweight, seen, i, weight + min(i, l))
                obj2 = dfs(neighbor, vertex, pathweight, seen, i + 1, weight + max(i, l))
                yield pathweight, obj1
                yield pathweight, obj2

    pairs = set()
    seen = [False] * (n + 2)
    pathweight = [-w] * (n + 2)
    for i in range(1, n + 1):
        if not seen[i]:
            for pathweight, pair in dfs(i, -1, pathweight, seen, 1, 0):
                if abs(pair[0] - pair[1]) <= w:
                    pairs.add(pair)
    return len(pairs)

