    for i in range(n-1, -1, -1):
        for j in range(m-1, -1, -1):
            if tiles[i][j] != "UL" or tiles[i][j+1] != "DR":
                return False
            if tiles[i][j] != "UR" or tiles[i][j+1] != "DR":
                return False
    return True

def solve(tiles1, tiles2):
    n, m = len(tiles1), len(tiles1[0])
    steps = []
    visited = [[False] * m for _ in range(n)]

    for r in range(n):
        for c in range(m):
            if tiles1[r][c] == tiles2[r][c] and visited[r][c] == False:
                q = deque([(r, c)])
                rotations = 0
                visited[r][c] = True

                while q:
                    new_q = deque()
                    while q:
                        x, y = q.popleft()
                        if tiles[x][y] == "UL":
                            tiles[x][y] = rotate_tiles(tiles1, tiles2)[0]
                            new_q.append((x-1, y))
                            new_q.append((x-1, y+1))
                        elif tiles[x][y] == "UR":
                            tiles[x][y] = rotate_tiles(tiles1, tiles2)[len(tiles1)-1]
                            new_q.append((x+1, y))
                            new_q.append((x+1, y+1))
