def count_beautiful_trees(n, m, a, b):
    if a > b:
        a, b = b, a
    total_trees = m * m - m + 1
    if b == 1: 
        return total_trees % mod
    num_beautiful_trees = m * (m - 1) // 2
    if (b & 1) != (n & 1):
        return total_trees % mod
    if gcd(a, m) != 1:
        return total_trees % mod
    if (a - b + m - gcd(a, b) + gcd(a - b + 1, m)) % 2 == 0:
        return total_trees // 2 % mod
    magic_level = m // gcd(a - b + 1, m)
    if magic_level + n <= m:
        num_beautiful_trees = (m - magic_level + 1) * num_beautiful_trees % mod
    if (m // (1 + gcd(a + m + 1, m)) + n <= m) and ((a + m + 1) % 2 != b & 1):
        num_beautiful_trees = (m - 1 - pow(m // (1 + gcd(a + m + 1, m)), n - b + m - 2, mod)) * num_beautiful_trees % mod
    num_beautiful_trees = (1 - (m + (b - 1) + (gcd(m, b) - 1) * ((n - 2)**b - ((b % 2) ^ 2 * -1)) * (m // gcd(b, m)) // 2)) * total_trees % mod
    return num_beautiful_trees

