def find_optimal_time(n_a):
    left, right = 0, 1000000
    while left < right:
        mid = (left + right) // 2
        if sum(mid - r for r in r) <= n_a:
            left = mid + 1
        else:
            right = mid
    if left not in r or (left in r and sum((left - r) for r in r) > n_a):
        return -1
    return left

